class Solution:
    def numOfWays(self, n: int) -> int:
        MOD = 10**9 + 7
        aba = 6
        abc = 6
        for _ in range(2, n + 1):
            new_aba = (3 * aba + 2 * abc) % MOD
            new_abc = (2 * aba + 2 * abc) % MOD
            aba, abc = new_aba, new_abc
        return (aba + abc) % MOD

class Solution {
public:
    int numOfWays(int n) {
        long long MOD = 1000000007;
        long long aba = 6, abc = 6;
        for (int i = 2; i <= n; ++i) {
            long long nextAba = (3 * aba + 2 * abc) % MOD;
            long long nextAbc = (2 * aba + 2 * abc) % MOD;
            aba = nextAba;
            abc = nextAbc;
        }
        return (aba + abc) % MOD;
    }
};

