var numOfWays = function(n) {
    const MOD = 1000000007n;
    let aba = 6n, abc = 6n;
    for (let i = 2; i <= n; i++) {
        const nextAba = (3n * aba + 2n * abc) % MOD;
        const nextAbc = (2n * aba + 2n * abc) % MOD;
        aba = nextAba;
